from taf.fdsw.rc.schemas.FDSW23B.certs import RootCertificate


class Certificates():

    def __init__(self, client):
        self._client = client

    def install_operator_certificates(self, pem_file_path_list, timeout=10):
        for cert in pem_file_path_list:
            with open(cert, "rb") as pem_file:
                pem_file_content = pem_file.read()

            self._client.send(
                method='config.certs.root.upload',
                timeout=timeout,
                payload=pem_file_content
            )

    def get_operator_certificates(self, timeout=10):
        resp = self._client.send(
            method='config.certs.root.fetch',
            timeout=timeout
        )
        root_certificates = [RootCertificate.from_object_dict(data=root_cert) for root_cert in resp.data]
        return root_certificates

    def delete_operator_certificates(self, cert_id, timeout=10):
        self._client.send(
            method='config.certs.root.delete',
            parameters={'id': cert_id},
            timeout=timeout
        )
